"""Contract tests for independent connection evidence; never real Spike passes."""
import copy
import json
from pathlib import Path
import pytest
import importlib.util
SPEC = importlib.util.spec_from_file_location('scenario_tcpip_test', Path(__file__).parent / 'acceptance/scenario_tcpip.py')
tcp = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(tcp)


def ipc_rows():
    return [dict(event='request', frame=dict(run_id='r', seq=1, kind='ready')),
            dict(event='response', frame=dict(run_id='r', seq=1, result={'identity': {'pid': 42, 'creation_time': 100}})),
            dict(event='request', frame=dict(run_id='r', seq=2, kind='start')),
            dict(event='response', frame=dict(run_id='r', seq=2, result={'probe': True}))]


def test_ipc_kind_pairing_not_sequence_constant():
    rows = ipc_rows()
    assert tcp.pair_ipc(rows, 'r', 'start') == (2, 3)
    assert tcp.pair_ipc(rows[2:], 'r', 'start') == (0, 1)
    rows[2]['frame']['seq'] = rows[3]['frame']['seq'] = 99
    assert tcp.pair_ipc(rows, 'r', 'start') == (2, 3)


@pytest.mark.parametrize('bad', ['missing', 'wrong_run', 'duplicate', 'reverse', 'ready'])
def test_ipc_ambiguous_or_wrong_stage_rejected(bad):
    rows = ipc_rows()
    if bad == 'missing': del rows[2]
    if bad == 'wrong_run': rows[3]['frame']['run_id'] = 'other'
    if bad == 'duplicate': rows.append(copy.deepcopy(rows[3]))
    if bad == 'reverse': rows[2], rows[3] = rows[3], rows[2]
    if bad == 'ready': rows = rows[:2]
    with pytest.raises(ValueError): tcp.pair_ipc(rows, 'r', 'start')


def line(t, body):
    return f'[00]0001.0002::2026-09-11 09:48:{t} [Microsoft-Windows-TCPIP] TCP: {body}\r\n'


def capture():
    return ('\ufeff' + ''.join([
        line('55.100000000', 'connection 0xAAA transition from ClosedState  to SynSentState , SndNxt = 0.'),
        line('55.200000000', 'connection 0xAAA transition from SynSentState  to EstablishedState , SndNxt = 1.'),
        line('55.200000100', 'connection 0xAAA (local=192.168.204.233:16633 remote=119.188.175.46:443) connect completed. PID = 7948.'),
        line('55.200000150', 'connection 0xBBB transition from ListenState to SynRcvdState , SndNxt = 0.'),
        line('55.200000200', 'listener (local=192.168.204.233:38927 remote=192.168.204.233:16633) accept completed. TCB = 0xBBB. PID = 404.'),
        line('56.000000000', 'connection 0xBBB transition from EstablishedState  to FinWait1State , SndNxt = 3.'),
        line('56.100000000', 'connection 0xAAA transition from EstablishedState  to CloseWaitState , SndNxt = 3.'),
        line('57.000000000', 'connection 0xAAA (local=192.168.204.233:16633 remote=119.188.175.46:443) close issued.'),
    ])).encode('utf-16-le')


def flow():
    return ('2026-09-11 09:48:55,201 INFO Diverter PROCESS_FLOW disposition=REDIRECT_TLS_RELAY pid=7948 proto=TCP src=192.168.204.233 sport=16633 dst=119.188.175.46 dport=443\n'
            '2026-09-11 09:48:55,201 INFO Diverter PROCESS_FLOW disposition=REINJECT_LOCAL pid=404 proto=TCP src=192.168.204.233 sport=38927 dst=192.168.204.233 dport=16633\n')


def reconstruct(raw=None, **kwargs):
    return tcp.connection_events(raw or capture(), 'pktmon.txt', kwargs.get('log', flow()),
                                 kwargs.get('pid', 7948), '192.168.204.233:16633',
                                 kwargs.get('dst', '119.188.175.46:443'), 404)


def test_exact_events_and_earliest_peer_transition():
    result = reconstruct()
    assert len(result['events']) == 8
    assert result['termination'][0]['kind'] == 'transition'
    assert 'FinWait1State' in result['termination'][0]['text']
    for event in result['events']:
        ref = event['ref']
        assert capture()[ref['byte_start']:ref['byte_end']].decode('utf-16-le') == event['text']


@pytest.mark.parametrize('bad', ['pid', 'tuple', 'peer', 'unknown', 'reuse', 'duplicate', 'no_end'])
def test_wrong_identity_unknown_lifecycle_and_incomplete_rejected(bad):
    raw = capture(); args = {}
    if bad == 'pid': args['pid'] = 99
    if bad == 'tuple': args['dst'] = '119.188.175.47:443'
    if bad == 'peer': args['log'] = flow().splitlines()[0]
    if bad == 'unknown': raw = raw.replace('CloseWaitState'.encode('utf-16-le'), 'MysteryState'.encode('utf-16-le'))
    if bad == 'reuse': raw += line('58.000000000', 'connection 0xAAA transition from ClosedState to SynSentState , SndNxt = 0.').encode('utf-16-le')
    if bad == 'duplicate': raw += line('58.000000000', 'connection 0xAAA (local=192.168.204.233:16633 remote=119.188.175.46:443) connect completed. PID = 7948.').encode('utf-16-le')
    if bad == 'no_end': raw = ('\ufeff'+''.join(capture().decode('utf-16-le').lstrip('\ufeff').splitlines(True)[:4])).encode('utf-16-le')
    with pytest.raises(ValueError): reconstruct(raw, **args)


def clocks_and_header(raw):
    import datetime as dt
    import hashlib
    base = int(dt.datetime(2026, 9, 11, 1, 48, 54, tzinfo=dt.timezone.utc).timestamp() * 10**7)
    guest = r'C:\run\pktmon.etl'
    header = f'[00]0000.0000::2026-09-11 09:48:54.000000000 [MSNT_SystemTrace] Header, EndTime: {base+116444736000000000+50000000}, StartTime: {base+116444736000000000}, EventsLost: 0, BuffersLost: 0, LogFileNameString: {guest}\r\n'
    raw = ('\ufeff' + header + raw.decode('utf-16-le').lstrip('\ufeff')).encode('utf-16-le')
    meta = dict(capture_mode='all-components-tcpip',
        clock_before=dict(utc_ticks=base+621355968000000000, mono=0, stopwatch_frequency=10000000, offset_minutes=480),
        clock_after=dict(utc_ticks=base+621355968000000000+50000000, mono=50000000, stopwatch_frequency=10000000, offset_minutes=480),
        conversion=dict(argv=['pktmon','etl2txt',guest,'--out',guest[:-4]+'.txt'], exit_code=0,
                        etl_sha256=hashlib.sha256(b'fixture ETL').hexdigest(), text_sha256=hashlib.sha256(raw).hexdigest()))
    return raw, meta


def test_capture_clock_header_and_conversion():
    raw, meta = clocks_and_header(capture())
    lo, hi = tcp.validate_capture(raw, b'fixture ETL', meta, 15625000)
    assert hi - lo == 5000000000


@pytest.mark.parametrize('bad', ['missing_clock','clock_step','timezone','frequency','etl_hash','text_hash','conversion','mode','loss','header'])
def test_capture_provenance_rejects_incomplete_or_changed(bad):
    import hashlib
    raw, meta = clocks_and_header(capture())
    if bad == 'missing_clock': del meta['clock_before']
    if bad == 'clock_step': meta['clock_after']['utc_ticks'] += 10000000
    if bad == 'timezone': meta['clock_before']['offset_minutes'] = 0
    if bad == 'frequency': meta['clock_after']['stopwatch_frequency'] = 1
    if bad == 'etl_hash': meta['conversion']['etl_sha256'] = '0'*64
    if bad == 'text_hash': meta['conversion']['text_sha256'] = '0'*64
    if bad == 'conversion': meta['conversion']['exit_code'] = 1
    if bad == 'mode': meta['capture_mode'] = 'packet-only'
    if bad == 'loss': raw = raw.replace('EventsLost: 0'.encode('utf-16-le'), 'EventsLost: 1'.encode('utf-16-le'))
    if bad == 'header': raw = capture()
    if bad in ('loss', 'header'): meta['conversion']['text_sha256'] = hashlib.sha256(raw).hexdigest()
    with pytest.raises((ValueError, KeyError)): tcp.validate_capture(raw, b'fixture ETL', meta, 15625000)


def oracle_case(tmp_path, native=None):
    import hashlib
    spec = importlib.util.spec_from_file_location('sst_etw_test', Path(__file__).parent/'acceptance/sst_fault_evidence.py')
    judge = importlib.util.module_from_spec(spec); spec.loader.exec_module(judge)
    files=[]
    def put(name, value, key='json:'):
        raw = value if isinstance(value, bytes) else (value.encode() if isinstance(value, str) else json.dumps(value).encode())
        (tmp_path/name).write_bytes(raw)
        files.append(dict(path=name, bytes=len(raw), sha256=hashlib.sha256(raw).hexdigest()))
        return dict(path=name, byte_start=0, byte_end=len(raw), event_key=key)
    receipt = put('receipt.json', dict(fault='policy_pause',nonce='n'))
    lower = put('receipt-metadata.json',dict(path='r/fault-triggered.json',bytes=files[0]['bytes'],sha256=files[0]['sha256'],created_utc='2026-09-11T01:48:55.5000000Z'))
    upper = put('stack.txt', 'LIVE STOP STACKS timestamp=1789091335.6', 'text')
    # Derive timestamps from the same tested parser to avoid an unrelated epoch typo.
    stamp=judge.iso_ns('2026-09-11T01:48:55.6000000Z')[0]/1e9
    (tmp_path/'stack.txt').unlink();files.pop();upper=put('stack.txt',f'LIVE STOP STACKS timestamp={stamp}', 'text')
    rows=ipc_rows();rows[1]['frame']['result']['identity']['pid']=404
    rows[1]['frame']['result']['identity']['creation_time']=str(116444736000000000+judge.iso_ns('2026-09-11T01:48:00.0000000Z')[0]//100)
    for row in rows: row['time']=stamp
    raw=('\n'.join(json.dumps(r) for r in rows)+'\n').encode();ipc=put('ipc.jsonl',raw)
    ipc.update(byte_start=sum(len((json.dumps(r)+'\n').encode()) for r in rows[:3]))
    creation=621355968000000000+judge.iso_ns('2026-09-11T01:48:00.0000000Z')[0]//100
    def probe(event, utc, **kw):
        ns=judge.iso_ns(utc)[0]
        return dict(event=event,utc_ticks=621355968000000000+ns//100,mono=ns//100,nonce='n',pid=7948,worker=0,seq=1,connection_id='n-1',**kw)
    ready=probe('ready','2026-09-11T01:48:55.0000000Z',creation_ticks=creation,stopwatch_frequency=10000000)
    established=probe('established','2026-09-11T01:48:55.3000000Z',src='192.168.204.233:16633',dst='119.188.175.46:443')
    end=probe('close','2026-09-11T01:48:56.5000000Z')
    probe_raw=('\n'.join(json.dumps(x) for x in (ready,established,end))+'\n').encode();put('probe.jsonl',probe_raw)
    a=len((json.dumps(ready)+'\n').encode());b=a+len((json.dumps(established)+'\n').encode())
    estref=dict(path='probe.jsonl',byte_start=a,byte_end=b,event_key='json:')
    endref=dict(estref,byte_start=b,byte_end=len(probe_raw))
    log=put('run.log',flow(),'text');log['byte_end']=len((flow().splitlines()[0]+'\n').encode())
    raw,meta=clocks_and_header(native or capture());put('pktmon.txt',raw,'text');put('pktmon.etl',b'fixture ETL');mr=put('meta.json',meta)
    observed=tcp.connection_events(raw,'pktmon.txt',flow(),7948,established['src'],established['dst'],404)
    case=dict(schema='sst.fault-evidence.case.v2',synthetic=True,case_id='test',candidate_id=judge.CANDIDATE,
        run_id='r',fault='policy_pause',nonce='n',clock=dict(domain='vm-utc',resolution_ns=15625000,discontinuities=[]),
        receipt_ref=receipt,start_response_ref=ipc,trigger=dict(lower_ref=lower,upper_ref=upper,success_refs=[upper]),
        session=dict(observation_kind='tcpip_etw',packet_refs=[],tuple_terminal_refs=[e['ref'] for e in observed['tuple_terminals']],generation_manifest=observed['generation_manifest'],connection_event_refs=[e['ref'] for e in observed['events']],
            connection_capture=dict(etl_path='pktmon.etl',text_path='pktmon.txt',metadata_ref=mr),
            probe_pid=7948,probe_creation=creation,src=established['src'],dst=established['dst'],
            established_ref=estref,managed_ref=log,end_ref=endref),
        health_refs=[],stop_refs=[],recovery_refs=[],exception_refs=[],files=files)
    return judge,case


def test_independent_oracle_rescans_all_events_and_rejects_late_boundary(tmp_path):
    judge,case=oracle_case(tmp_path)
    def checks():return {x['id']:x for x in judge.assess(case,tmp_path)['checks']}
    assert checks()['start_attribution']['passed'] is False  # fixture has no init_evidence, not healthy qualification
    assert checks()['overlap']['passed'], checks()['overlap']
    assert judge.assess(case,tmp_path)['passed'] is False
    original=copy.deepcopy(case)
    case['session']['connection_event_refs']=[r for r in case['session']['connection_event_refs'] if 'FinWait1State' not in judge.Evidence(tmp_path,case['files']).read(r)]
    assert not checks()['overlap']['passed']
    case=copy.deepcopy(original);case['session']['packet_refs']=[case['session']['connection_event_refs'][0]]
    assert not checks()['overlap']['passed']
    case=copy.deepcopy(original);case['schema']='sst.fault-evidence.case.v1'
    assert not checks()['overlap']['passed']
    case=copy.deepcopy(original);case['session']['probe_creation']+=10**10
    assert not checks()['overlap']['passed']
    case=copy.deepcopy(original);case['session']['connection_event_refs'].reverse()
    assert not checks()['overlap']['passed']


def test_observed_native_termination_dialect():
    bodies = [
        'connection 0xFFFFD48FE08E8A20 (local=192.168.204.233:16633 remote=119.188.175.46:443) shutdown initiated (本地系统已终止传输连接。). PID = 7948.',
        'connection 0xFFFFD48FE0D68740 (local=192.168.204.233:38927 remote=192.168.204.233:16633) connection terminated: received RST.',
        'Connection 0xFFFFD48FE08E8A20 Transport (Protocol TCP , AddressFamily = IPV4 ) sent RST with Local = 192.168.204.233:16633, Remote = 119.188.175.46:443. Reason = Connection aborted .',
    ]
    for body in bodies:
        assert tcp.parse_line(line('57.000000000', body), {})['terminal']
    # Generic normalization: any parenthesized shutdown reason collapses to
    # the bare terminal verb; unknown reason text no longer causes rejection
    # (each Windows localization/variant was blocking real scenarios).
    event = tcp.parse_line(line('57.000000000', bodies[0].replace('本地系统已终止传输连接。','未知原因')), {})
    assert event['terminal'] and event['kind'] == 'shutdown initiated'


def test_other_tcb_same_original_tuple_rst_cannot_be_ignored():
    extra=line('55.400000000','Connection 0xCCC Transport (Protocol TCP , AddressFamily = IPV4 ) sent RST with Local = 192.168.204.233:16633, Remote = 119.188.175.46:443. Reason = Connection aborted .')
    with pytest.raises(ValueError): reconstruct(capture()+extra.encode('utf-16-le'))


def test_selected_tcb_cannot_change_pid():
    raw=capture().replace('close issued.'.encode('utf-16-le'),'close issued. PID = 99999.'.encode('utf-16-le'))
    with pytest.raises(ValueError): reconstruct(raw)


def test_unrelated_ipv6_is_outside_bound_connection():
    unrelated = line('55.150000000', 'connection 0xCCC (local=[::1]:12 remote=[::1]:13) connect completed. PID = 1.')
    assert len(reconstruct(capture() + unrelated.encode('utf-16-le'))['events']) == 8


def test_flow_reference_cannot_use_earlier_different_destination(tmp_path):
    import hashlib
    judge,case = oracle_case(tmp_path)
    wrong = flow().splitlines()[0].replace('119.188.175.46', '119.188.175.47').replace('55,201', '54,201')+'\n'
    raw=(wrong+flow()).encode();(tmp_path/'run.log').write_bytes(raw)
    for entry in case['files']:
        if entry['path']=='run.log':entry.update(bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())
    case['session']['managed_ref'].update(byte_start=0,byte_end=len(wrong.encode()))
    checks={x['id']:x for x in judge.assess(case,tmp_path)['checks']}
    assert not checks['overlap']['passed']
    assert 'exact outbound tuple' in checks['overlap']['reason']


def test_adapter_cli_persists_precise_failure_without_fabricated_case(tmp_path):
    import subprocess, sys
    descriptor = tmp_path/'capture.json'
    descriptor.write_text(json.dumps(dict(raw={},fault='policy_pause',run_id='r',nonce='n',candidate_id='candidate',scenario_id='s')))
    output = tmp_path/'result.json'
    argv=[sys.executable,str(Path(__file__).parent/'acceptance/scenario_fault_evidence.py'),
          '--evidence-root',str(tmp_path),'--capture',str(descriptor),'--output',str(output)]
    process=subprocess.run(argv,text=True,capture_output=True)
    assert process.returncode == 3, process.stderr
    result=json.loads(output.read_text())
    assert result['passed'] is False
    assert result['checks'][0]['id']=='case_construction'
    assert 'receipt' in result['checks'][0]['reason']
    assert not output.with_suffix('.case.json').exists()
    original=output.read_bytes()
    assert subprocess.run(argv,capture_output=True).returncode != 0
    assert output.read_bytes()==original


def reused_capture():
    old = [line('54.000000000', 'connection 0xAAA (local=192.168.204.233:28787 remote=192.168.204.1:45000) exists. State = EstablishedState . PID = 99.'),
           line('54.100000000', 'connection 0xAAA transition from EstablishedState to ClosedState , SndNxt = 0.')]
    return ('\ufeff'+''.join(old)+capture().decode('utf-16-le').lstrip('\ufeff')).encode('utf-16-le')


def test_proven_reuse_keeps_boundary_manifest_not_old_termination():
    result = reconstruct(reused_capture())
    assert result['generation_manifest'][0]['left_censored'] is True
    assert result['connect']['generation_ordinal'] == 1
    assert all('54.' not in row['text'] for row in result['events'])
    assert result['termination'][0]['transition'] == ('Established', 'FinWait1')


@pytest.mark.parametrize('bad',['missing_closed','missing_birth','wrong_old_identity'])
def test_generation_cannot_be_guessed(bad):
    raw=reused_capture().decode('utf-16-le')
    if bad=='missing_closed':raw=''.join(x for x in raw.splitlines(True) if '54.100000000' not in x)
    if bad=='missing_birth':raw=''.join(x for x in raw.splitlines(True) if '55.100000000' not in x)
    if bad=='wrong_old_identity':raw=raw.replace('PID = 7948.', 'PID = 99.')
    with pytest.raises(ValueError):reconstruct(raw.encode('utf-16-le'))


def test_multiline_shutdown_preserves_entire_record_and_pid():
    body='connection 0xAAA (local=192.168.204.233:16633 remote=119.188.175.46:443) shutdown initiated ({设备超时}\r\r\n在 %hs 上指定的 I/O 操作无法在超时过期之前完成。). PID = 7948.'
    raw=('\ufeff'+line('57.000000000',body)).encode('utf-16-le')
    records=list(tcp.byte_records(raw,'trace'))
    assert len(records)==1
    event=tcp.parse_line(*records[0]);assert event['terminal'] and event['pid']==7948
    assert raw[event['ref']['byte_start']:event['ref']['byte_end']].decode('utf-16-le')==event['text']


