def kernel_fixture():
    import hashlib
    meta=copy.deepcopy(KERNEL_META);etl=b'synthetic ETL payload, never runtime qualification'
    meta['conversion']['etl_sha256']=hashlib.sha256(etl).hexdigest()
    return KERNEL_EVENTS,etl,KERNEL_HEADER,KERNEL_SUMMARY,meta


def test_kernel_full_conversion_and_send_binding():
    mod=kernel_module();observed=mod.validate_capture(*kernel_fixture(),'events.jsonl')
    match=mod.match_send(observed['events'],KERNEL_PROBE,KERNEL_PROBE['creation_ticks'])
    assert match['pid']==KERNEL_PROBE['pid']
    for key,value in [('pid',1),('src','192.168.204.233:1'),('actual_dst','192.168.204.1:1'),('byte_count',1),('send_before_ticks',KERNEL_PROBE['send_after_ticks']+1)]:
        with pytest.raises(ValueError):mod.match_send(observed['events'],dict(KERNEL_PROBE,**{key:value}),KERNEL_PROBE['creation_ticks'])
    with pytest.raises(ValueError):mod.match_send(observed['events']*2,KERNEL_PROBE,KERNEL_PROBE['creation_ticks'])
    with pytest.raises(ValueError):mod.match_send(observed['events'],KERNEL_PROBE,KERNEL_PROBE['send_after_ticks']+1)


@pytest.mark.parametrize('bad',['clock','offset','etl_hash','events_hash','header_hash','summary_hash','conversion','header_loss','summary_loss','session','order'])
def test_kernel_full_provenance_cannot_be_downgraded(bad):
    import hashlib
    raw,etl,header,summary,meta=kernel_fixture()
    if bad=='clock':meta['clock_after']['utc_ticks']+=10**7
    if bad=='offset':meta['clock_after']['offset_minutes']=479
    if bad.endswith('_hash'):meta['conversion'][bad.replace('_hash','_sha256')]='0'*64
    if bad=='conversion':meta['conversion']['event_reader_exit_code']=1
    if bad=='header_loss':
        text=header.decode('utf-8-sig');text=text.replace('<Data Name="EventsLost">       0</Data>','<Data Name="EventsLost">       1</Data>');header=text.encode();meta['conversion']['header_sha256']=hashlib.sha256(header).hexdigest()
    if bad=='summary_loss':summary=summary.replace(b'Total Events  Lost      0',b'Total Events  Lost      1');meta['conversion']['summary_sha256']=hashlib.sha256(summary).hexdigest()
    if bad=='session':meta['session_name']='another-run'
    if bad=='order':
        lines=raw.splitlines();raw=b'\n'.join(reversed(lines))+b'\n';meta['conversion']['events_sha256']=hashlib.sha256(raw).hexdigest()
    with pytest.raises((ValueError,KeyError)):kernel_module().validate_capture(raw,etl,header,summary,meta,'events.jsonl')


def null_rst(t='57.100000000'):
    return line(t, 'Connection 0x0 Transport (Protocol TCP , AddressFamily = IPV4 ) sent RST with Local = 192.168.204.233:16633, Remote = 119.188.175.46:443. Reason = Receive discarded .').encode('utf-16-le')


def test_null_terminal_is_separate_negative_constraint():
    result = reconstruct(capture() + null_rst())
    assert len(result['tuple_terminals']) == 1
    event = result['tuple_terminals'][0]
    assert event['kind'] == 'unattributed_tuple_terminal'
    assert 'pid' not in event
    assert event not in result['events'] and event not in result['termination']
    assert all(g['tcb'] != '0X0' for g in result['generation_manifest'])


@pytest.mark.parametrize('bad', ['foreign', 'reason', 'no_named_end', 'second_pid'])
def test_null_terminal_does_not_supply_missing_identity_or_end(bad):
    raw = capture(); extra = null_rst()
    if bad == 'foreign': extra = extra.replace('0x0'.encode('utf-16-le'), '0xCCC'.encode('utf-16-le'))
    if bad == 'reason': extra = extra.replace('Receive discarded'.encode('utf-16-le'), 'Unknown reason'.encode('utf-16-le'))
    if bad == 'no_named_end': raw = ('\ufeff'+''.join(raw.decode('utf-16-le').lstrip('\ufeff').splitlines(True)[:5])).encode('utf-16-le')
    if bad == 'second_pid': raw += line('58.000000000', 'connection 0xCCC (local=192.168.204.233:16633 remote=119.188.175.46:443) connect completed. PID = 999.').encode('utf-16-le')
    with pytest.raises(ValueError): reconstruct(raw + extra)


@pytest.mark.parametrize('time,passed', [('57.100000000', True), ('55.800000000', True),
                                         ('55.550000000', False), ('55.100000000', False)])
def test_null_terminal_conservative_overlap(tmp_path, time, passed):
    judge, case = oracle_case(tmp_path, capture() + null_rst(time))
    check = next(x for x in judge.assess(case, tmp_path)['checks'] if x['id'] == 'overlap')
    assert check['passed'] is passed, check


@pytest.mark.parametrize('bad', ['omit', 'duplicate', 'reorder', 'named_refs', 'generation'])
def test_null_terminal_full_reference_set_required(tmp_path, bad):
    judge, case = oracle_case(tmp_path, capture() + null_rst('55.800000000') + null_rst())
    session = case['session']
    if bad == 'omit': session['tuple_terminal_refs'].pop(0)
    if bad == 'duplicate': session['tuple_terminal_refs'].append(session['tuple_terminal_refs'][0])
    if bad == 'reorder': session['tuple_terminal_refs'].reverse()
    if bad == 'named_refs': session['connection_event_refs'].extend(session['tuple_terminal_refs'])
    if bad == 'generation': session['generation_manifest'][0]['record_refs'].extend(session['tuple_terminal_refs'])
    check = next(x for x in judge.assess(case, tmp_path)['checks'] if x['id'] == 'overlap')
    assert not check['passed'], check


@pytest.mark.parametrize('bad', ['missing_id', 'other_id', 'other_pid', 'duplicate_establish'])
def test_null_terminal_rejects_probe_ambiguity(bad):
    origin = dict(event='established', pid=1, nonce='n', connection_id='c', src='1.1.1.1:1', dst='2.2.2.2:2')
    rows = [origin.copy()]
    if bad == 'missing_id': origin.pop('connection_id'); rows = [origin.copy()]
    if bad == 'other_id': rows.append(dict(origin, event='send', connection_id='retry'))
    if bad == 'other_pid': rows.append(dict(origin, event='send', pid=2))
    if bad == 'duplicate_establish': rows.append(origin.copy())
    with pytest.raises(ValueError): tcp.validate_tuple_probe(rows, origin, origin['src'], origin['dst'])


