@pytest.mark.parametrize('time,passed,late_flow', [('57.100000000', True, None), ('55.310000000', False, None), ('55.800000000', True, 'peer'), ('55.800000000', False, 'main')])
def test_application_consumer_applies_null_terminal_uncertainty(tmp_path, time, passed, late_flow):
    import sys
    sys.path.insert(0, str(Path(__file__).parent / 'acceptance'))
    import scenario_suite as suite
    judge, case = oracle_case(tmp_path, capture() + null_rst(time))
    # Feed the production application consumer full originals, keeping native
    # conversion metadata intact; filenames are the capture export contract.
    (tmp_path/'ipc.jsonl').rename(tmp_path/'ipc-parent.jsonl')
    (tmp_path/'meta.json').rename(tmp_path/'pktmon-nic.json')
    rows = [json.loads(line) for line in (tmp_path/'probe.jsonl').read_bytes().splitlines()]
    runner = suite.Suite.__new__(suite.Suite)
    runner.root = tmp_path
    runner.identity = type('Identity', (), {'candidate_id': judge.CANDIDATE})()
    if late_flow:
        with (tmp_path/'run.log').open('a', newline='') as stream:
            stream.write(flow().splitlines()[1 if late_flow == 'peer' else 0].replace('55,201', '55,790')+'\n')
    records = [suite.file_record(path, tmp_path) for path in tmp_path.iterdir()]
    run = {'run_id': 'r', 'capture': {'files': records}, 'originals': {'files': []}}
    def assess():
        return runner._application_observation(run, rows[1], [rows[2]], 'n', rows[1]['src'], rows[1]['dst'], 'TCP')
    if passed:
        observation = assess()
        assert len(observation['tuple_terminal_refs']) == 1
        native = min(judge.iso_ns('2026-09-11T01:48:56.0000000Z')[0], judge.iso_ns('2026-09-11T01:48:'+time+'Z')[0])
        assert observation['end_lower_ns'] == native - 15624999
    else:
        with pytest.raises(suite.SuiteError, match='lifetime'):
            assess()


@pytest.mark.parametrize('body', [
    'connection 0xFFFFD48FE2CC5050 send keep-alive at SndUna = 2007798549.',
    'SWS avoidance began on connection 0xFFFFD48FE132A9D0. Timer set for 5000 ms. BytesToSend = 0x10E, SendAvailable = 23062, Cwnd = 14870, MaxSndWnd = 0xFC00.',
])
def test_precise_native_context_is_not_positive_or_terminal(body):
    event = tcp.parse_line(line('57.000000000', body), {})
    assert event['kind'] == 'transport context'
    assert not event['terminal']
    assert not any(k in event for k in ('pid', 'local', 'remote', 'transition'))
    for bad in (body + ' extra', body.replace(' = ', ' = -', 1), body[:-1]):
        with pytest.raises(ValueError): tcp.parse_line(line('57.000000000', bad), {})


def test_curl_policy_window_keeps_outside_same_tuple_as_context():
    import sys
    sys.path.insert(0, str(Path(__file__).parent/'acceptance'))
    from sst_fault_evidence import iso_ns
    lo = iso_ns('2026-09-11T01:48:55.0000000Z')[0]
    window = (lo, lo + 500000000)
    late = flow().splitlines()[0].replace('55,201', '57,201').replace('REDIRECT_TLS_RELAY', 'DIVERT_FAKE') + '\n'
    rows = tcp.policy_partition(flow()+late, 'run.log', 7948, '192.168.204.233:16633', '119.188.175.46:443', window)
    assert len(rows['inside']) == len(rows['outside']) == 1
    result = tcp.connection_events(capture(), 'pktmon.txt', flow()+late, 7948,
        '192.168.204.233:16633', '119.188.175.46:443', 404, policy_window=window)
    assert result['connect']['pid'] == 7948


@pytest.mark.parametrize('time', ['55,000', '55,499'])
def test_curl_policy_window_boundary_snaps_inside(time):
    import sys
    sys.path.insert(0, str(Path(__file__).parent/'acceptance'))
    from sst_fault_evidence import iso_ns
    lo = iso_ns('2026-09-11T01:48:55.0000000Z')[0]
    # Point-based classification: the timestamp point is within the window
    # [55.000, 55.500], so it classifies as inside rather than raising the
    # old band-straddling uncertainty error (discovery100-31 regression fix).
    result = tcp.policy_partition(flow().replace('55,201', time), 'run.log', 7948,
        '192.168.204.233:16633', '119.188.175.46:443', (lo, lo+500000000))
    assert result['inside'], f'expected inside for timestamp {time}'


@pytest.mark.parametrize('bad', ['second', 'outside_dns', 'inside_conflict', 'second_generation'])
def test_curl_multiple_tuple_policy_conflict_and_generation_fail(bad):
    from sst_fault_evidence import iso_ns
    lo = iso_ns('2026-09-11T01:48:55.0000000Z')[0]
    started = dict(pid=7948, dns_ipv4=['119.188.175.46'], creation_ticks=100, dns_before_ticks=99)
    log = flow()
    if bad == 'second': log += flow().splitlines()[0].replace('sport=16633', 'sport=16634')+'\n'
    if bad == 'outside_dns': log += flow().splitlines()[0].replace('119.188.175.46', '8.8.8.8')+'\n'
    if bad in ('second', 'outside_dns'):
        with pytest.raises(ValueError): tcp.curl_tuple(log, started)
        return
    assert tcp.curl_tuple(log+log, started) == ('192.168.204.233:16633', '119.188.175.46:443')
    if bad == 'inside_conflict': log += flow().splitlines()[0].replace('REDIRECT_TLS_RELAY', 'DIVERT_FAKE')+'\n'
    raw = capture()
    if bad == 'second_generation':
        raw += line('58.000000000', 'connection 0xAAA transition from CloseWaitState to ClosedState , SndNxt = 1.').encode('utf-16-le')
        raw += line('58.100000000', 'connection 0xAAA transition from ClosedState to SynSentState , SndNxt = 1.').encode('utf-16-le')
        raw += line('58.200000000', 'connection 0xAAA (local=192.168.204.233:16633 remote=119.188.175.46:443) connect completed. PID = 7948.').encode('utf-16-le')
    with pytest.raises(ValueError):
        tcp.connection_events(raw, 'pktmon.txt', log, 7948, '192.168.204.233:16633',
                              '119.188.175.46:443', 404, policy_window=(lo,lo+500000000))


def test_application_curl_window_preserves_context_from_full_originals(tmp_path):
    import scenario_suite as suite
    judge, case = oracle_case(tmp_path)
    (tmp_path/'ipc.jsonl').rename(tmp_path/'ipc-parent.jsonl')
    (tmp_path/'meta.json').rename(tmp_path/'pktmon-nic.json')
    rows = [json.loads(line) for line in (tmp_path/'probe.jsonl').read_bytes().splitlines()]
    rows[1].update(event='curl_started', creation_ticks=rows[0]['utc_ticks'],
                   dns_before_ticks=rows[0]['utc_ticks']-1, dns_ipv4=['119.188.175.46'])
    rows[2].update(event='curl_completed', exit_code=0, http_code='401')
    (tmp_path/'probe.jsonl').write_text('\n'.join(json.dumps(x) for x in rows)+'\n', newline='')
    late = flow().splitlines()[0].replace('55,201','57,201').replace('REDIRECT_TLS_RELAY','DIVERT_FAKE')+'\n'
    with (tmp_path/'run.log').open('a', newline='') as stream: stream.write(late)
    runner = suite.Suite.__new__(suite.Suite); runner.root = tmp_path
    runner.identity = type('Identity', (), {'candidate_id': judge.CANDIDATE})()
    run = {'run_id':'r','capture':{'files':[suite.file_record(p,tmp_path) for p in tmp_path.iterdir()]},'originals':{'files':[]}}
    obs = runner._application_observation(run, rows[1], [rows[2]], 'n', rows[1]['src'], rows[1]['dst'], 'TCP', rows[1]['creation_ticks'])
    assert len(obs['policy_refs']) == 2  # primary and peer
    assert len(obs['policy_context_refs']) == 1
    ref = obs['policy_context_refs'][0]
    assert (tmp_path/ref['path']).read_bytes()[ref['byte_start']:ref['byte_end']].decode() == late
    assert len(obs['connection_refs']) == 8


def test_curl_upstream_cannot_borrow_primary_socket_or_packet_repeats():
    from sst_fault_evidence import iso_ns
    lo = iso_ns('2026-09-11T01:48:55.0000000Z')[0]
    window = (lo, lo+500000000)
    def event(t, port):
        return f'2026-09-11 09:48:{t} INFO Diverter ALLOW_INTERNAL_UPSTREAM ip=119.188.175.46 kind=tls_relay port=443 sport={port}\n'
    primary = event('54,201',111)
    curl = event('55,201',222)
    tail = event('55,499',222)
    args = ('ALLOW_INTERNAL_UPSTREAM',dict(ip='119.188.175.46',kind='tls_relay',port='443'),window,('ip','port','sport','kind'))
    assert tcp.scoped_log_event(primary+curl+tail,*args) == curl.strip()
    assert tcp.scoped_log_event(primary,*args) is None
    with pytest.raises(ValueError,match='ambiguous'):
        tcp.scoped_log_event(primary+curl+event('55,301',333),*args)


def test_status_success_shutdown_is_terminal_not_establishment():
    body = 'connection 0xAAA (local=192.168.204.233:16633 remote=119.188.175.46:443) shutdown initiated (STATUS_SUCCESS). PID = 7948.'
    event = tcp.parse_line(line('55.500000000', body), {})
    assert event['terminal'] and event['kind'] == 'shutdown initiated'
    assert event['pid'] == 7948
    raw = capture().decode('utf-16-le').replace(line('56.000000000', 'connection 0xBBB transition from EstablishedState  to FinWait1State , SndNxt = 3.'), line('55.500000000', body) + line('56.000000000', 'connection 0xBBB transition from EstablishedState  to FinWait1State , SndNxt = 3.')).encode('utf-16-le')
    result = reconstruct(raw)
    assert result['termination'][0]['kind'] == 'shutdown initiated'
    assert result['connect']['kind'] == 'connect completed'


