def test_tcp_bh_lifecycle_is_transport_context_not_terminal():
    def bh_line(body):
        return line('57.000000000', body)
    for body in ('connection 0xFFFFD48FDC1344E0 entered BH, BH MSS 536, original MSS 1460.',
                 'connection 0xFFFFD48FDC1344E0 Exiting BH due to full ack received, BH mss 536, Original MSS 1460.'):
        event = tcp.parse_line(bh_line(body), {})
        assert event['kind'] == 'transport context' and event.get('bh') is True
        assert event['tcb'] == '0XFFFFD48FDC1344E0'
        assert not event.get('terminal')


def test_tcp_bh_all_diagnostic_variants_are_transport_context():
    for body in (
        'connection 0xFFFFD48FDC1344E0 entered BH, BH MSS 536, original MSS 1460.',
        'connection 0xFFFFD48FDC1344E0 Exiting BH due to full ack received, BH mss 536, Original MSS 1460.',
        'connection 0xFFFFD48FDC1344E0 Exiting BH due to timeout on TCB, BH mss 536, Original MSS 1460.',
        'connection 0xFFFFD48FDC1344E0 not entering BH due to FULL ack received on TCB.',
        'connection 0xFFFFD48FDC1344E0 not entering BH due to not enough data unacked.',
    ):
        event = tcp.parse_line(line('57.000000000', body), {})
        assert event['kind'] == 'transport context' and event.get('bh') is True
        assert not event.get('terminal')


def test_tcp_bh_generic_matches_all_diagnostic_variants():
    for body in (
        'connection 0xFFFFD48FDC1344E0 entered BH, BH MSS 536, original MSS 1460.',
        'connection 0xFFFFD48FDC1344E0 Exiting BH due to full ack received, BH mss 536, Original MSS 1460.',
        'connection 0xFFFFD48FDC1344E0 Exiting BH due to timeout on TCB, BH mss 536, Original MSS 1460.',
        'connection 0xFFFFD48FDC1344E0 not entering BH due to FULL ack received on TCB.',
        'connection 0xFFFFD48FDC1344E0 not entering BH due to not enough data unacked.',
        'connection 0xFFFFD48FDC1344E0 not entering BH due to max data retransmission exceeded.',
        'connection 0xFFFFD48FDC1344E0 Exiting BH due to some future reason, BH mss 1300, Original MSS 1460.',
        'connection 0xFFFFD48FDC1344E0 not entering BH due to another future cause.',
    ):
        event = tcp.parse_line(line('57.000000000', body), {})
        assert event['kind'] == 'transport context' and event.get('bh') is True
        assert not event.get('terminal')
